# Generated by Termeric. User configuration is loaded first.
if [[ ${TERMERIC_BASH_CUSTOM_RC-0} == 1 ]]; then
    declare +x __termeric_user_rc="${TERMERIC_BASH_RCFILE-}"
else
    declare +x __termeric_user_rc="$HOME/.bashrc"
fi
unset TERMERIC_BASH_CUSTOM_RC TERMERIC_BASH_RCFILE TERMERIC_BASH_INTEGRATION_RC
# Native --rcfile paths are not searched through PATH. Keep relative paths
# relative to this startup directory, and keep empty filenames empty.
if [[ -n $__termeric_user_rc && $__termeric_user_rc != /* ]]; then
    declare +x __termeric_user_rc="./$__termeric_user_rc"
fi
if [[ -n $__termeric_user_rc && -r $__termeric_user_rc ]]; then
    builtin source -- "$__termeric_user_rc"
fi
unset __termeric_user_rc
